// ============================================================
//  QUANTUM FLUX v2.1 — by Yogender
// ============================================================

// --- Configuration ---
const PARTICLE_COUNT = 15000;
const SWARM_FORCE = 0.5;
const SHAPE_FORCE = 0.2;
const DAMPING = 0.96;
const PINCH_THRESHOLD = 0.08;
const SOFTENING = 50;
const MAX_VEL = 30;
const SUPERNOVA_TRIGGER_DIST = 150;
const SUPERNOVA_DETONATE_DIST = 40;
const EXPLOSION_FORCE = 80;
const COOLDOWN_DURATION = 1.5;
const PINCH_BOOST_MULTIPLIER = 3.0;
const COLOR_POS = { r: 0.3, g: 0.7, b: 1.0 };
const COLOR_NEG = { r: 1.0, g: 0.3, b: 0.5 };
const COLOR_FLASH = { r: 1.0, g: 1.0, b: 1.0 };
const COLOR_BATTLE = { r: 1.0, g: 0.9, b: 0.2 };
const RENDER_PIXEL_RATIO = Math.min(window.devicePixelRatio || 1, 1.35);

// --- State ---
let currentShape = 'swarm';
let width = window.innerWidth;
let height = window.innerHeight;
let isSwarmMode = true;
let isPinching = false;
let pinchDistance = 0;
let handCenter = new THREE.Vector3();
let indexFingerTip = new THREE.Vector3();
let lastHandTime = 0;

const hands = {
    left: { active: false, pos: new THREE.Vector3(), pinch: false, charge: 1, lastSeen: 0 },
    right: { active: false, pos: new THREE.Vector3(), pinch: false, charge: 1, lastSeen: 0 }
};
const detectedIndexPoints = [
    { pos: new THREE.Vector3(), pinch: false, pinchDistance: 1, lastSeen: 0, landmarks: null },
    { pos: new THREE.Vector3(), pinch: false, pinchDistance: 1, lastSeen: 0, landmarks: null }
];
const lastLandmarks = { left: null, right: null };
const supernova = { state: 'IDLE', charge: 0, explosionTime: 0, epicenter: new THREE.Vector3() };
const particleOwner = new Uint8Array(PARTICLE_COUNT);
for (let i = 0; i < PARTICLE_COUNT; i++) particleOwner[i] = i % 2;

// === BATTLE / KAMEHAMEHA 2.0 — Two-Player Combat ===
const BATTLE_PROJECTILE_COUNT = 3000; // particles dedicated to projectiles
const BATTLE_SHIELD_RADIUS = 130;
const BATTLE_PROJECTILE_SPEED = 18;
const BATTLE_HIT_RADIUS = 60;

// Each player state
function makeFighter(side) {
    return {
        side: side,                // 'left' | 'right'
        pos: new THREE.Vector3(),  // anchor (index finger position)
        active: false,
        charging: false,           // pinch held
        chargeAmount: 0,           // 0..1
        shielding: false,          // thumbs up
        shieldStrength: 0,         // 0..1 (smooth in/out)
        hp: 100,
        hitFlash: 0,               // 0..1 visual feedback
        // Active beam fired by THIS fighter
        beam: {
            active: false,
            origin: new THREE.Vector3(),
            target: new THREE.Vector3(),
            head: new THREE.Vector3(),
            dir: new THREE.Vector3(),
            speed: 0,
            life: 0,
            maxLife: 2.5,
            power: 0,
            collided: false
        }
    };
}

const battle = {
    p1: makeFighter('left'),   // left hand
    p2: makeFighter('right'),  // right hand
    explosions: [],            // active burst effects
    roundOver: false,
    roundResetTime: 0,
    winner: null
};

// === AUDIO ===
let audioCtx = null, analyser = null, audioSourceNode = null, audioElement = null;
let micStream = null, micSourceNode = null;
let audioFreqData = null;
let bassEnergy = 0, midEnergy = 0, trebleEnergy = 0;
let beatPulse = 0, lastBeatTime = 0;
let isMusicLoaded = false, isMusicPlaying = false, musicReactivityEnabled = false;
let audioMode = 'none'; // 'none' | 'file' | 'mic'

// === SCORE / HUD ===
let supernovaCount = 0, kamehamehaCount = 0, beatHitCount = 0;
let comboCount = 0, comboTimer = 0;

// === SCREEN SHAKE ===
let shakeAmount = 0;

// --- Three.js ---
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x000000, 0.0006);
const camera = new THREE.PerspectiveCamera(75, width / height, 1, 4000);
camera.position.z = 800;
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(width, height);
renderer.setPixelRatio(RENDER_PIXEL_RATIO);
document.body.appendChild(renderer.domElement);

// === GLOW TEXTURE ===
function makeGlowTexture() {
    const size = 64;
    const cv = document.createElement('canvas');
    cv.width = size; cv.height = size;
    const ctx = cv.getContext('2d');
    const grad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
    grad.addColorStop(0, 'rgba(255,255,255,1)');
    grad.addColorStop(0.2, 'rgba(255,255,255,0.85)');
    grad.addColorStop(0.5, 'rgba(255,255,255,0.25)');
    grad.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = grad; ctx.fillRect(0, 0, size, size);
    const tex = new THREE.CanvasTexture(cv);
    tex.needsUpdate = true;
    return tex;
}
const glowTexture = makeGlowTexture();

// --- Particles ---
const geometry = new THREE.BufferGeometry();
const pPos = new Float32Array(PARTICLE_COUNT * 3);
const pVel = new Float32Array(PARTICLE_COUNT * 3);
const pCol = new Float32Array(PARTICLE_COUNT * 3);
const originalColors = new Float32Array(PARTICLE_COUNT * 3);
const shapeTargets = new Float32Array(PARTICLE_COUNT * 3);

for (let i = 0; i < PARTICLE_COUNT; i++) {
    const r = 1000 * Math.random();
    pPos[i * 3] = (Math.random() - 0.5) * r;
    pPos[i * 3 + 1] = (Math.random() - 0.5) * r;
    pPos[i * 3 + 2] = (Math.random() - 0.5) * r;
    const choice = Math.random();
    let rC, gC, bC;
    if (choice < 0.3) { rC = 0.1; gC = 0.5; bC = 1.0; }
    else if (choice < 0.5) { rC = 0.6; gC = 0.0; bC = 1.0; }
    else if (choice < 0.7) { rC = 1.0; gC = 0.8; bC = 0.2; }
    else { rC = 0.0; gC = 1.0; bC = 0.9; }
    pCol[i * 3] = rC; pCol[i * 3 + 1] = gC; pCol[i * 3 + 2] = bC;
    originalColors[i * 3] = rC; originalColors[i * 3 + 1] = gC; originalColors[i * 3 + 2] = bC;
}

geometry.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
geometry.setAttribute('color', new THREE.BufferAttribute(pCol, 3));

const material = new THREE.PointsMaterial({
    size: 4.0, map: glowTexture, vertexColors: true,
    blending: THREE.AdditiveBlending, depthTest: false,
    transparent: true, opacity: 0.85
});
const particles = new THREE.Points(geometry, material);
scene.add(particles);

// --- Starfield ---
const starGeo = new THREE.BufferGeometry();
const STAR_COUNT = 5000;
const sPos = new Float32Array(STAR_COUNT * 3);
const sCol = new Float32Array(STAR_COUNT * 3);
for (let i = 0; i < STAR_COUNT; i++) {
    const r = 2000 + Math.random() * 3000;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    sPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    sPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
    sPos[i * 3 + 2] = r * Math.cos(phi);
    const type = Math.random();
    let c = new THREE.Color();
    if (type > 0.9) c.setHex(0xffaaaa);
    else if (type > 0.7) c.setHex(0xaaccff);
    else c.setHex(0xffffff);
    const b = 0.5 + Math.random() * 0.5;
    sCol[i * 3] = c.r * b; sCol[i * 3 + 1] = c.g * b; sCol[i * 3 + 2] = c.b * b;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3));
starGeo.setAttribute('color', new THREE.BufferAttribute(sCol, 3));
const starMat = new THREE.PointsMaterial({ size: 1.5, vertexColors: true, fog: false, transparent: true, opacity: 0.8 });
const starField = new THREE.Points(starGeo, starMat);
starField.frustumCulled = false;
scene.add(starField);

// --- Helpers ---
const origin = new THREE.Vector3(0, 0, 0);
const singleForceOut = { vx: 0, vy: 0, vz: 0 };
function clamp(v, mn, mx) { return Math.max(mn, Math.min(mx, v)); }
function lerpValue(a, b, t) { return a + (b - a) * t; }

function resetSupernova() { supernova.state = 'IDLE'; supernova.charge = 0; supernova.explosionTime = 0; supernova.epicenter.set(0, 0, 0); }
function resetBattle() {
    battle.p1 = makeFighter('left');
    battle.p2 = makeFighter('right');
    battle.explosions = [];
    battle.roundOver = false;
    battle.roundResetTime = 0;
    battle.winner = null;
}

// === BATTLE HELPERS ===
function detectThumbsUp(landmarks) {
    if (!landmarks) return false;
    // Thumb tip (4) above thumb IP (3) above MCP (2) — i.e. thumb pointing up
    // Other fingers folded: tip y > pip y means folded (since y increases downward)
    const thumbUp = landmarks[4].y < landmarks[3].y - 0.04;
    const indexFolded  = landmarks[8].y  > landmarks[6].y;
    const middleFolded = landmarks[12].y > landmarks[10].y;
    const ringFolded   = landmarks[16].y > landmarks[14].y;
    return thumbUp && (indexFolded || middleFolded) && ringFolded;
}

function spawnExplosion(pos, color, power) {
    battle.explosions.push({
        pos: pos.clone(),
        color: color || { r: 1, g: 0.7, b: 0.2 },
        life: 1.0,
        power: power || 1.0,
        radius: 0
    });
    if (battle.explosions.length > 6) battle.explosions.shift();
    shakeAmount = Math.max(shakeAmount, 25 * (power || 1));
}

function fireBattleBeam(fighter, enemy) {
    if (fighter.beam.active) return;
    const beam = fighter.beam;
    beam.active = true;
    beam.origin.copy(fighter.pos);
    beam.head.copy(fighter.pos);
    beam.target.copy(enemy.pos);
    const dx = enemy.pos.x - fighter.pos.x;
    const dy = enemy.pos.y - fighter.pos.y;
    const dz = enemy.pos.z - fighter.pos.z;
    const len = Math.sqrt(dx*dx + dy*dy + dz*dz) || 1;
    beam.dir.set(dx/len, dy/len, dz/len);
    beam.speed = BATTLE_PROJECTILE_SPEED * (0.7 + fighter.chargeAmount * 0.6);
    beam.life = 0;
    beam.power = fighter.chargeAmount;
    beam.collided = false;
    fighter.charging = false;
    fighter.chargeAmount = 0;
    kamehamehaCount++;
    addCombo();
    flashHud(fighter.side === 'left' ? '⚡ P1 FIRES!' : '⚡ P2 FIRES!');
    shakeAmount = Math.max(shakeAmount, 15);
}

function updateFighterFromHand(fighter, hand, landmarks) {
    if (!hand.active) {
        fighter.active = false;
        fighter.charging = false;
        fighter.shielding = false;
        return;
    }
    fighter.active = true;
    fighter.pos.copy(hand.pos);

    const wasCharging = fighter.charging;
    const isPinching = hand.pinch;
    const isThumbsUp = landmarks ? detectThumbsUp(landmarks) : false;

    fighter.shielding = isThumbsUp;
    fighter.shieldStrength += ((isThumbsUp ? 1.0 : 0) - fighter.shieldStrength) * 0.15;

    // Charging logic — only while NOT shielding
    if (!fighter.shielding && isPinching) {
        fighter.charging = true;
        fighter.chargeAmount = Math.min(1, fighter.chargeAmount + 0.018);
    } else if (wasCharging && !isPinching && !fighter.shielding) {
        // Released → fire toward enemy
        const enemy = (fighter === battle.p1) ? battle.p2 : battle.p1;
        if (enemy.active && fighter.chargeAmount > 0.2) {
            fireBattleBeam(fighter, enemy);
        } else {
            fighter.chargeAmount = 0;
            fighter.charging = false;
        }
    } else if (!isPinching) {
        fighter.charging = false;
        fighter.chargeAmount *= 0.92; // decay if just released without firing
    }

    // Hit flash decay
    fighter.hitFlash *= 0.9;
}

function updateBeam(fighter, enemy) {
    const beam = fighter.beam;
    if (!beam.active) return;

    beam.life += 0.016;
    // Move beam head forward
    beam.head.x += beam.dir.x * beam.speed;
    beam.head.y += beam.dir.y * beam.speed;
    beam.head.z += beam.dir.z * beam.speed;

    // Collision with enemy
    if (enemy.active) {
        const dx = beam.head.x - enemy.pos.x;
        const dy = beam.head.y - enemy.pos.y;
        const dz = beam.head.z - enemy.pos.z;
        const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
        if (dist < BATTLE_HIT_RADIUS) {
            if (enemy.shielding && enemy.shieldStrength > 0.5) {
                // SHIELD BLOCK → bounce explosion
                spawnExplosion(beam.head, { r: 0.4, g: 0.8, b: 1.0 }, 0.6);
                flashHud(enemy === battle.p1 ? '🛡️ P1 BLOCKED!' : '🛡️ P2 BLOCKED!');
            } else {
                // DIRECT HIT → enemy explodes
                spawnExplosion(enemy.pos, { r: 1.0, g: 0.4, b: 0.1 }, 1.5 + beam.power);
                enemy.hp -= 25 + beam.power * 25;
                enemy.hitFlash = 1.0;
                if (enemy.hp <= 0 && !battle.roundOver) {
                    battle.roundOver = true;
                    battle.winner = (fighter === battle.p1) ? 'P1' : 'P2';
                    battle.roundResetTime = 0;
                    flashHud('🏆 ' + battle.winner + ' WINS!');
                    shakeAmount = 60;
                } else {
                    flashHud(enemy === battle.p1 ? '💥 P1 HIT!' : '💥 P2 HIT!');
                }
            }
            beam.active = false;
            beam.collided = true;
            return;
        }
    }

    // Beam-vs-beam collision
    const otherBeam = enemy.beam;
    if (otherBeam.active) {
        const dx = beam.head.x - otherBeam.head.x;
        const dy = beam.head.y - otherBeam.head.y;
        const dz = beam.head.z - otherBeam.head.z;
        const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
        if (dist < BATTLE_HIT_RADIUS) {
            const midX = (beam.head.x + otherBeam.head.x) * 0.5;
            const midY = (beam.head.y + otherBeam.head.y) * 0.5;
            const midZ = (beam.head.z + otherBeam.head.z) * 0.5;
            spawnExplosion(new THREE.Vector3(midX, midY, midZ), { r: 1.0, g: 1.0, b: 0.8 }, 2.0);
            flashHud('💥 BEAM CLASH!');
            beam.active = false;
            otherBeam.active = false;
            beam.collided = true;
            return;
        }
    }

    // Auto-expire
    if (beam.life > beam.maxLife) {
        beam.active = false;
    }
}

function worldPosFromLandmark(indexTip, target) {
    const vFOV = camera.fov * Math.PI / 180;
    const visibleHeight = 2 * Math.tan(vFOV / 2) * camera.position.z;
    const visibleWidth = visibleHeight * camera.aspect;
    target.set((1 - indexTip.x - 0.5) * visibleWidth, -(indexTip.y - 0.5) * visibleHeight, 0);
}

function updatePrimaryHandState() {
    const primary = hands.left.active ? hands.left : (hands.right.active ? hands.right : null);
    if (primary) {
        indexFingerTip.copy(primary.pos);
        isPinching = primary.pinch;
        lastHandTime = primary.lastSeen;
        handCenter.copy(indexFingerTip);
    } else { isPinching = false; }
}

function assignIndexPointToHand(hand, detected, now) {
    const lerpFactor = now - hand.lastSeen > 250 ? 0.3 : 0.82;
    if (hand.lastSeen === 0) hand.pos.copy(detected.pos);
    else hand.pos.lerp(detected.pos, lerpFactor);
    hand.active = true; hand.pinch = detected.pinch; hand.lastSeen = now;
}

function applySingleHandForces(px, py, pz, vx, vy, vz, target) {
    const dx = target.x - px, dy = target.y - py, dz = target.z - pz;
    const distSq = dx * dx + dy * dy + dz * dz + 100;
    const pull = 2000 / distSq;
    vx += dx * pull * SWARM_FORCE; vy += dy * pull * SWARM_FORCE; vz += dz * pull * SWARM_FORCE;
    const distToFinger = Math.sqrt(dx * dx + dy * dy + dz * dz) + 1;
    if (distToFinger < 150) {
        const push = (150 - distToFinger) * 0.05;
        vx -= (dx / distToFinger) * push; vy -= (dy / distToFinger) * push; vz -= (dz / distToFinger) * push;
    }
    vx += dx * 0.0002; vy += dy * 0.0002; vz += dz * 0.0002;
    const dist = Math.sqrt(dx * dx + dy * dy + 100);
    vx += (dy / dist) * 0.5; vy -= (dx / dist) * 0.5;
    if (px * px + py * py + pz * pz > 500000) {
        vx -= px * 0.0001; vy -= py * 0.0001; vz -= pz * 0.0001;
    }
    singleForceOut.vx = vx; singleForceOut.vy = vy; singleForceOut.vz = vz;
    return singleForceOut;
}

function applyDuelHandForces(px, py, pz, vx, vy, vz, hand) {
    const dx = hand.pos.x - px, dy = hand.pos.y - py, dz = hand.pos.z - pz;
    const distSq = dx * dx + dy * dy + dz * dz + 100;
    const dist = Math.sqrt(distSq);
    const boost = hand.pinch ? PINCH_BOOST_MULTIPLIER : 1.0;
    const pull = (2000 * boost) / distSq;
    vx += dx * pull * SWARM_FORCE; vy += dy * pull * SWARM_FORCE; vz += dz * pull * SWARM_FORCE;
    if (dist < 150) {
        const push = (150 - dist) * 0.05;
        vx -= (dx / dist) * push; vy -= (dy / dist) * push; vz -= (dz / dist) * push;
    }
    vx += dx * 0.0002; vy += dy * 0.0002; vz += dz * 0.0002;
    const d2D = Math.sqrt(dx * dx + dy * dy + 100);
    vx += (dy / d2D) * 0.4; vy -= (dx / d2D) * 0.4;
    if (px * px + py * py + pz * pz > 500000) {
        vx -= px * 0.0001; vy -= py * 0.0001; vz -= pz * 0.0001;
    }
    singleForceOut.vx = vx; singleForceOut.vy = vy; singleForceOut.vz = vz;
    return singleForceOut;
}

function triggerSupernova(positions, colors, midpoint) {
    supernova.state = 'EXPLODING'; supernova.charge = 1; supernova.explosionTime = 0;
    supernova.epicenter.copy(midpoint);
    shakeAmount = Math.max(shakeAmount, 25);
    supernovaCount++; addCombo();
    flashHud('💥 SUPERNOVA');
    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const ix = i * 3, iy = ix + 1, iz = ix + 2;
        const rx = positions[ix] - supernova.epicenter.x + (Math.random() - 0.5) * 8;
        const ry = positions[iy] - supernova.epicenter.y + (Math.random() - 0.5) * 8;
        const rz = positions[iz] - supernova.epicenter.z + (Math.random() - 0.5) * 8;
        const dist = Math.sqrt(rx * rx + ry * ry + rz * rz) || 1;
        pVel[ix] += (rx / dist) * EXPLOSION_FORCE;
        pVel[iy] += (ry / dist) * EXPLOSION_FORCE;
        pVel[iz] += (rz / dist) * EXPLOSION_FORCE;
        colors[ix] = COLOR_FLASH.r; colors[iy] = COLOR_FLASH.g; colors[iz] = COLOR_FLASH.b;
    }
}

// === SHAPES ===
function generateShape(type) {
    const arr = new Float32Array(PARTICLE_COUNT * 3);
    for (let i = 0; i < PARTICLE_COUNT; i++) {
        let x = 0, y = 0, z = 0;
        if (type === 'heart') {
            const t = Math.random() * Math.PI * 2;
            x = 16 * Math.pow(Math.sin(t), 3) * 15;
            y = (13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t)) * 15;
            z = (Math.random() - 0.5) * 100;
        } else if (type === 'saturn') {
            const isRing = Math.random() > 0.4;
            if (isRing) {
                const a = Math.random() * Math.PI * 2, r = 250 + Math.random() * 150;
                x = Math.cos(a) * r; z = Math.sin(a) * r; y = (Math.random() - 0.5) * 10;
            } else {
                const r = 180, theta = Math.random() * Math.PI * 2, phi = Math.acos(2 * Math.random() - 1);
                x = r * Math.sin(phi) * Math.cos(theta);
                y = r * Math.sin(phi) * Math.sin(theta);
                z = r * Math.cos(phi);
            }
            const tilt = 0.4, tx = x;
            x = tx * Math.cos(tilt) - y * Math.sin(tilt);
            y = tx * Math.sin(tilt) + y * Math.cos(tilt);
        } else if (type === 'flower') {
            const k = 4, theta = Math.random() * Math.PI * 2;
            const rc = Math.cos(k * theta), r = 300 * Math.abs(rc) + 50;
            x = r * Math.cos(theta); y = r * Math.sin(theta);
            z = -rc * 100 + (Math.random() - 0.5) * 50;
        } else if (type === 'fireworks') {
            const r = 300 + Math.random() * 300;
            const theta = Math.random() * Math.PI * 2, phi = Math.acos(2 * Math.random() - 1);
            x = r * Math.sin(phi) * Math.cos(theta);
            y = r * Math.sin(phi) * Math.sin(theta);
            z = r * Math.cos(phi);
        }
        arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
    }
    return arr;
}

window.setShape = (shape) => {
    currentShape = shape;
    isSwarmMode = (shape === 'swarm');
    const isDuelMode = (shape === 'duel');
    const isBattleMode = (shape === 'battle');
    if (!isDuelMode) resetSupernova();
    if (!isBattleMode) resetBattle();

    const manualPanel = document.getElementById('manual');
    if (manualPanel) manualPanel.classList.remove('open');
    const audioPanel = document.getElementById('audioPanel');
    if (audioPanel) audioPanel.classList.remove('open');

    if (!isSwarmMode && !isDuelMode && !isBattleMode) {
        const targets = generateShape(shape);
        for (let i = 0; i < targets.length; i++) shapeTargets[i] = targets[i];
    }

    document.querySelectorAll('#ui button[data-mode]').forEach(b => b.classList.remove('active'));
    const btn = document.querySelector('#ui button[data-mode="' + shape + '"]');
    if (btn) btn.classList.add('active');

    for (let i = 0; i < PARTICLE_COUNT * 3; i++) pVel[i] *= 0.1;

    // Show battle hint
    if (isBattleMode) flashHud('⚔ BATTLE MODE');
};

window.toggleFullscreen = () => {
    if (!document.fullscreenElement) document.documentElement.requestFullscreen();
    else if (document.exitFullscreen) document.exitFullscreen();
};
window.toggleManual = (evt) => {
    if (evt) evt.stopPropagation();
    const panel = document.getElementById('manual');
    if (panel) panel.classList.toggle('open');
};
document.addEventListener('click', (e) => {
    const panel = document.getElementById('manual');
    const manualBtn = document.querySelector('#ui button[data-action="manual"]');
    if (panel && panel.classList.contains('open') && !panel.contains(e.target) && e.target !== manualBtn) {
        panel.classList.remove('open');
    }
    const audioPanel = document.getElementById('audioPanel');
    const musicBtn = document.getElementById('musicBtn');
    if (audioPanel && audioPanel.classList.contains('open') && !audioPanel.contains(e.target) && e.target !== musicBtn) {
        audioPanel.classList.remove('open');
    }
});

// === AUDIO ===
function initAudio() {
    if (audioCtx) return;
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    analyser = audioCtx.createAnalyser();
    analyser.fftSize = 512;
    analyser.smoothingTimeConstant = 0.78;
    audioFreqData = new Uint8Array(analyser.frequencyBinCount);
}

function disconnectAllAudio() {
    if (audioElement) { audioElement.pause(); audioElement.src = ''; audioElement = null; }
    if (audioSourceNode) { try { audioSourceNode.disconnect(); } catch (e) { } audioSourceNode = null; }
    if (micSourceNode) { try { micSourceNode.disconnect(); } catch (e) { } micSourceNode = null; }
    if (micStream) { micStream.getTracks().forEach(t => t.stop()); micStream = null; }
    isMusicPlaying = false; musicReactivityEnabled = false; isMusicLoaded = false;
    audioMode = 'none';
}

window.handleMusicUpload = (input) => {
    const file = input.files[0];
    if (!file) return;
    initAudio();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    disconnectAllAudio();
    audioElement = new Audio();
    audioElement.src = URL.createObjectURL(file);
    audioElement.crossOrigin = 'anonymous';
    audioElement.loop = true;
    audioSourceNode = audioCtx.createMediaElementSource(audioElement);
    audioSourceNode.connect(analyser);
    analyser.connect(audioCtx.destination);
    audioElement.play().catch(e => console.warn('Play blocked:', e));
    isMusicLoaded = true; isMusicPlaying = true; musicReactivityEnabled = true;
    audioMode = 'file';
    updateMusicBtnUI();
    flashHud('🎵 MUSIC LOADED');
    document.getElementById('audioPanel').classList.remove('open');
};

window.loadMusicFromUrl = () => {
    const url = document.getElementById('audioUrl').value.trim();
    if (!url) { alert('Paste a direct .mp3 / .wav / .ogg URL'); return; }
    initAudio();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    disconnectAllAudio();
    audioElement = new Audio();
    audioElement.src = url;
    audioElement.crossOrigin = 'anonymous';
    audioElement.loop = true;
    audioElement.addEventListener('error', () => {
        alert('Could not load that URL.\n\nNote: YouTube/Spotify links DO NOT work due to browser CORS security.\n\nUse:\n• Local MP3 file (Upload button)\n• Direct .mp3 URL from a CORS-enabled host\n• Microphone (sing/play music near mic)');
        flashHud('❌ URL FAILED');
    });
    audioElement.addEventListener('canplay', () => {
        try {
            audioSourceNode = audioCtx.createMediaElementSource(audioElement);
            audioSourceNode.connect(analyser);
            analyser.connect(audioCtx.destination);
            audioElement.play();
            isMusicLoaded = true; isMusicPlaying = true; musicReactivityEnabled = true;
            audioMode = 'file';
            updateMusicBtnUI();
            flashHud('🎵 URL LOADED');
            document.getElementById('audioPanel').classList.remove('open');
        } catch (e) {
            alert('CORS blocked this URL. Use a local file or microphone.');
        }
    });
};

window.useMicrophone = async () => {
    initAudio();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    disconnectAllAudio();
    try {
        micStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
        micSourceNode = audioCtx.createMediaStreamSource(micStream);
        micSourceNode.connect(analyser);
        // DON'T connect to destination → no feedback
        isMusicLoaded = true; isMusicPlaying = true; musicReactivityEnabled = true;
        audioMode = 'mic';
        updateMusicBtnUI();
        flashHud('🎤 MIC ACTIVE');
        document.getElementById('audioPanel').classList.remove('open');
    } catch (e) {
        alert('Microphone permission denied or unavailable.');
    }
};

window.stopAudio = () => {
    disconnectAllAudio();
    updateMusicBtnUI();
    flashHud('🔇 AUDIO OFF');
    document.getElementById('audioPanel').classList.remove('open');
};

window.toggleMusic = (evt) => {
    if (evt) evt.stopPropagation();
    const panel = document.getElementById('audioPanel');
    if (panel) panel.classList.toggle('open');
};

function updateMusicBtnUI() {
    const btn = document.getElementById('musicBtn');
    if (!btn) return;
    if (audioMode === 'file' && isMusicPlaying) btn.textContent = '♫ Playing';
    else if (audioMode === 'mic') btn.textContent = '🎤 Mic';
    else btn.textContent = '♫ Audio';
    btn.classList.toggle('active', isMusicPlaying);
}

function updateAudioAnalysis() {
    if (!analyser || !musicReactivityEnabled) {
        bassEnergy *= 0.94; midEnergy *= 0.94; trebleEnergy *= 0.94; beatPulse *= 0.9;
        return;
    }
    analyser.getByteFrequencyData(audioFreqData);
    let bass = 0, mid = 0, treb = 0;
    for (let i = 0; i < 8; i++) bass += audioFreqData[i];
    bass /= (8 * 255);
    for (let i = 8; i < 40; i++) mid += audioFreqData[i];
    mid /= (32 * 255);
    for (let i = 40; i < 120; i++) treb += audioFreqData[i];
    treb /= (80 * 255);
    bassEnergy = bass; midEnergy = mid; trebleEnergy = treb;
    if (bass > 0.55 && Date.now() - lastBeatTime > 220) {
        beatPulse = 1.0; lastBeatTime = Date.now();
        beatHitCount++; addCombo();
        shakeAmount = Math.max(shakeAmount, 8);
    }
    beatPulse *= 0.88;
}

// === HUD ===
function addCombo() { comboCount++; comboTimer = 90; }
function updateCombo() { if (comboTimer > 0) comboTimer--; else comboCount = 0; }
function updateHud() {
    const el = document.getElementById('hud');
    if (!el) return;
    let battleStatus = '';
    if (currentShape === 'battle') {
        const p1 = battle.p1, p2 = battle.p2;
        battleStatus =
            '<div class="hud-battle">' +
              '<div class="hud-fighter">' +
                '<span>P1 ' + (p1.shielding ? '🛡️' : (p1.charging ? '⚡' : '👤')) + '</span>' +
                '<div class="hp-bar"><div class="hp-fill p1" style="width:' + Math.max(0, p1.hp) + '%"></div></div>' +
              '</div>' +
              '<div class="hud-fighter">' +
                '<span>P2 ' + (p2.shielding ? '🛡️' : (p2.charging ? '⚡' : '👤')) + '</span>' +
                '<div class="hp-bar"><div class="hp-fill p2" style="width:' + Math.max(0, p2.hp) + '%"></div></div>' +
              '</div>' +
            '</div>';
    }
    el.innerHTML =
        '<div class="hud-row"><span>SUPERNOVA</span><b>' + supernovaCount + '</b></div>' +
        '<div class="hud-row"><span>KAMEHAMEHA</span><b>' + kamehamehaCount + '</b></div>' +
        '<div class="hud-row"><span>BEATS</span><b>' + beatHitCount + '</b></div>' +
        battleStatus +
        (comboCount > 1 ? '<div class="hud-combo">x' + comboCount + ' COMBO</div>' : '');
}
function flashHud(text) {
    const el = document.getElementById('hud-flash');
    if (!el) return;
    el.textContent = text;
    el.classList.remove('show');
    void el.offsetWidth;
    el.classList.add('show');
}

// --- MediaPipe ---
const videoElement = document.getElementsByClassName('input_video')[0];

function onResults(results) {
    document.getElementById('loading').style.display = 'none';
    hands.left.active = false; hands.right.active = false;
    hands.left.pinch = false; hands.right.pinch = false;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
        const now = Date.now();
        let detectedCount = 0;
        for (let i = 0; i < results.multiHandLandmarks.length && detectedCount < 2; i++) {
            const lm = results.multiHandLandmarks[i];
            const indexTip = lm[8], thumbTip = lm[4], wrist = lm[0];
            const handSize = Math.sqrt(Math.pow(indexTip.x - wrist.x, 2) + Math.pow(indexTip.y - wrist.y, 2));
            if (handSize < 0.05 || handSize > 0.8) continue;
            const dx = indexTip.x - thumbTip.x, dy = indexTip.y - thumbTip.y;
            const dist = Math.sqrt(dx * dx + dy * dy);
            const detected = detectedIndexPoints[detectedCount];
            worldPosFromLandmark(indexTip, detected.pos);
            detected.pinch = dist < PINCH_THRESHOLD;
            detected.pinchDistance = dist;
            detected.lastSeen = now;
            pinchDistance = dist; lastHandTime = now;
            detectedCount++;
        }
        if (detectedCount === 2 && detectedIndexPoints[0].pos.x > detectedIndexPoints[1].pos.x) {
            const a = detectedIndexPoints[0], b = detectedIndexPoints[1];
            const tx = a.pos.x, ty = a.pos.y, tz = a.pos.z, tp = a.pinch, td = a.pinchDistance;
            a.pos.copy(b.pos); a.pinch = b.pinch; a.pinchDistance = b.pinchDistance;
            b.pos.set(tx, ty, tz); b.pinch = tp; b.pinchDistance = td;
        }
        if (detectedCount > 0) assignIndexPointToHand(hands.left, detectedIndexPoints[0], now);
        if (detectedCount > 1) assignIndexPointToHand(hands.right, detectedIndexPoints[1], now);
    }
    updatePrimaryHandState();
}

const handTracker = new Hands({ locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}` });
handTracker.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.4, minTrackingConfidence: 0.4 });
handTracker.onResults(onResults);
const cameraUtils = new Camera(videoElement, {
    onFrame: async () => await handTracker.send({ image: videoElement }),
    width: 480, height: 360
});
cameraUtils.start();

// === BATTLE LOGIC (FIXED) ===
function updateBattleState() {
    const lmLeft  = lastLandmarks.left;
    const lmRight = lastLandmarks.right;

    updateFighterFromHand(battle.p1, hands.left,  lmLeft);
    updateFighterFromHand(battle.p2, hands.right, lmRight);

    updateBeam(battle.p1, battle.p2);
    updateBeam(battle.p2, battle.p1);

    // Update explosions
    for (let i = battle.explosions.length - 1; i >= 0; i--) {
        const e = battle.explosions[i];
        e.life -= 0.025;
        e.radius += 8;
        if (e.life <= 0) battle.explosions.splice(i, 1);
    }

    // Round reset after winner
    if (battle.roundOver) {
        battle.roundResetTime += 0.016;
        if (battle.roundResetTime > 3.0) {
            resetBattle();
        }
    }
}

// --- Animation Loop ---
let time = 0;

function animate() {
    requestAnimationFrame(animate);
    time += 0.01;
    material.color.setHex(0xffffff);

    updateAudioAnalysis();
    updateCombo();
    updateHud();

    const positions = particles.geometry.attributes.position.array;
    const colors = particles.geometry.attributes.color.array;
    const isDuelMode = currentShape === 'duel';
    const isBattleMode = currentShape === 'battle';
    const singleActiveHand = hands.left.active ? hands.left : (hands.right.active ? hands.right : null);
    const hasTwoHands = hands.left.active && hands.right.active;

    // Audio-reactive visuals
    material.size = 4.0 + bassEnergy * 4.5 + beatPulse * 2.5;
    material.opacity = 0.7 + trebleEnergy * 0.3;
    scene.fog.density = 0.0006 + midEnergy * 0.0008;

    if (isSwarmMode && Date.now() - lastHandTime > 1000) {
        indexFingerTip.lerp(origin, 0.05);
        isPinching = false;
    }

    if (isBattleMode) updateBattleState();

    // Supernova trigger (duel mode) — only when both hands active and NOT both pinching
    if (isDuelMode && hasTwoHands && !(hands.left.pinch && hands.right.pinch)) {
        const ax = hands.right.pos.x - hands.left.pos.x;
        const ay = hands.right.pos.y - hands.left.pos.y;
        const az = hands.right.pos.z - hands.left.pos.z;
        const rawDist = Math.sqrt(ax * ax + ay * ay + az * az);
        const mx = (hands.left.pos.x + hands.right.pos.x) * 0.5;
        const my = (hands.left.pos.y + hands.right.pos.y) * 0.5;
        const mz = (hands.left.pos.z + hands.right.pos.z) * 0.5;
        if (supernova.state !== 'EXPLODING' && supernova.state !== 'COOLDOWN') {
            if (rawDist < SUPERNOVA_DETONATE_DIST) {
                triggerSupernova(positions, colors, new THREE.Vector3(mx, my, mz));
            } else if (rawDist < SUPERNOVA_TRIGGER_DIST) {
                supernova.state = 'CHARGING';
                supernova.charge = 1 - (rawDist / SUPERNOVA_TRIGGER_DIST);
                supernova.epicenter.set(mx, my, mz);
            } else if (supernova.state === 'CHARGING') resetSupernova();
        }
    } else if (isDuelMode && supernova.state === 'CHARGING') resetSupernova();

    if (supernova.state === 'EXPLODING') {
        supernova.explosionTime += 0.016;
        if (supernova.explosionTime > 0.25) { supernova.state = 'COOLDOWN'; supernova.explosionTime = 0; }
    } else if (supernova.state === 'COOLDOWN') {
        supernova.explosionTime += 0.016;
        if (supernova.explosionTime > COOLDOWN_DURATION) resetSupernova();
    }

    const timeScale = time * 3.0;

    for (let i = 0; i < PARTICLE_COUNT; i++) {
        const ix = i * 3, iy = i * 3 + 1, iz = i * 3 + 2;
        let px = positions[ix], py = positions[iy], pz = positions[iz];
        let vx = pVel[ix], vy = pVel[iy], vz = pVel[iz];
        let tr, tg, tb;

        // ===== COLOR =====
        if (isBattleMode) {
            const ownerIsP1 = particleOwner[i] === 0;
            const myFighter = ownerIsP1 ? battle.p1 : battle.p2;

            // Base color: P1 = blue, P2 = orange/gold
            if (ownerIsP1) {
                tr = 0.3; tg = 0.7; tb = 1.0;
            } else {
                tr = 1.0; tg = 0.6; tb = 0.2;
            }

            // Charging → white-hot
            if (myFighter.charging) {
                tr = lerpValue(tr, 1.0, myFighter.chargeAmount * 0.85);
                tg = lerpValue(tg, 1.0, myFighter.chargeAmount * 0.7);
                tb = lerpValue(tb, 0.8, myFighter.chargeAmount * 0.5);
            }

            // Beam particles → bright yellow-white
            if (myFighter.beam.active) {
                const beam = myFighter.beam;
                const rx = px - beam.origin.x;
                const ry = py - beam.origin.y;
                const along = rx * beam.dir.x + ry * beam.dir.y;
                const trailLen = Math.sqrt(
                    (beam.head.x - beam.origin.x)**2 + (beam.head.y - beam.origin.y)**2
                );
                if (along > -30 && along < trailLen + 80) {
                    tr = 1.0; tg = 0.95; tb = 0.6;
                }
            }

            // Shield → cyan glow
            if (myFighter.shieldStrength > 0.1) {
                tr = lerpValue(tr, 0.4, myFighter.shieldStrength * 0.6);
                tg = lerpValue(tg, 0.9, myFighter.shieldStrength * 0.6);
                tb = lerpValue(tb, 1.0, myFighter.shieldStrength * 0.6);
            }

            // Hit flash → red
            if (myFighter.hitFlash > 0.05) {
                tr = lerpValue(tr, 1.0, myFighter.hitFlash);
                tg = lerpValue(tg, 0.1, myFighter.hitFlash);
                tb = lerpValue(tb, 0.1, myFighter.hitFlash);
            }

            // Explosion glow override
            for (let e = 0; e < battle.explosions.length; e++) {
                const exp = battle.explosions[e];
                const dx = px - exp.pos.x;
                const dy = py - exp.pos.y;
                const dz = pz - exp.pos.z;
                const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
                if (dist < exp.radius + 80) {
                    const t = exp.life * 0.8;
                    tr = lerpValue(tr, exp.color.r, t);
                    tg = lerpValue(tg, exp.color.g, t);
                    tb = lerpValue(tb, exp.color.b, t);
                }
            }
        } else if (isDuelMode && (hasTwoHands || singleActiveHand)) {
            const ownerIsLeft = particleOwner[i] === 0;
            tr = ownerIsLeft ? COLOR_POS.r : COLOR_NEG.r;
            tg = ownerIsLeft ? COLOR_POS.g : COLOR_NEG.g;
            tb = ownerIsLeft ? COLOR_POS.b : COLOR_NEG.b;
            if (hasTwoHands) {
                const myHand = ownerIsLeft ? hands.left : hands.right;
                if (myHand.pinch) {
                    tr = lerpValue(tr, 1.0, 0.6);
                    tg = lerpValue(tg, 0.8, 0.6);
                    tb = lerpValue(tb, 0.0, 0.6);
                }
            } else if (singleActiveHand && singleActiveHand.pinch) {
                tr = lerpValue(tr, 1.0, 0.6);
                tg = lerpValue(tg, 0.8, 0.6);
                tb = lerpValue(tb, 0.0, 0.6);
            }
            if (supernova.state === 'CHARGING') {
                const f = supernova.charge * 0.7;
                tr = lerpValue(tr, COLOR_FLASH.r, f);
                tg = lerpValue(tg, COLOR_FLASH.g, f);
                tb = lerpValue(tb, COLOR_FLASH.b, f);
            } else if (supernova.state === 'EXPLODING') {
                tr = COLOR_FLASH.r; tg = COLOR_FLASH.g; tb = COLOR_FLASH.b;
            } else if (supernova.state === 'COOLDOWN') {
                const cp = supernova.explosionTime / COOLDOWN_DURATION;
                tr = lerpValue(COLOR_FLASH.r, tr, cp);
                tg = lerpValue(COLOR_FLASH.g, tg, cp);
                tb = lerpValue(COLOR_FLASH.b, tb, cp);
            }
        } else if (isDuelMode) {
            tr = originalColors[ix]; tg = originalColors[iy]; tb = originalColors[iz];
        } else if (isPinching) {
            tr = 1.0;
            tg = 0.5 + 0.5 * Math.sin(timeScale + i * 0.005);
            tb = 0.0;
        } else {
            tr = originalColors[ix]; tg = originalColors[iy]; tb = originalColors[iz];
        }

        if (musicReactivityEnabled && trebleEnergy > 0.1) {
            const shimmer = trebleEnergy * 0.3 * Math.sin(timeScale + i * 0.01);
            tr = clamp(tr + shimmer, 0, 1);
            tb = clamp(tb + shimmer * 0.5, 0, 1);
        }

        colors[ix] += (tr - colors[ix]) * 0.12;
        colors[iy] += (tg - colors[iy]) * 0.12;
        colors[iz] += (tb - colors[iz]) * 0.12;

        // ===== PHYSICS =====
        if (isBattleMode) {
            // Decide which fighter "owns" this particle (split 50/50)
            const ownerIsP1 = particleOwner[i] === 0;
            const myFighter = ownerIsP1 ? battle.p1 : battle.p2;
            const enemyFighter = ownerIsP1 ? battle.p2 : battle.p1;

            let handled = false;

            // 1) BEAM PARTICLES — if my fighter's beam is active, some particles ride it
            if (myFighter.beam.active && (i % 3 === 0)) {
                const beam = myFighter.beam;
                const trailLen = Math.sqrt(
                    (beam.head.x - beam.origin.x) ** 2 +
                    (beam.head.y - beam.origin.y) ** 2
                );
                // Project particle onto beam line
                const rx = px - beam.origin.x;
                const ry = py - beam.origin.y;
                const rz = pz - beam.origin.z;
                const along = rx * beam.dir.x + ry * beam.dir.y + rz * beam.dir.z;

                if (along > -50 && along < trailLen + 100) {
                    // Pull onto beam axis
                    const targetX = beam.origin.x + beam.dir.x * along;
                    const targetY = beam.origin.y + beam.dir.y * along;
                    const targetZ = beam.origin.z + beam.dir.z * along;
                    vx += (targetX - px) * 0.15;
                    vy += (targetY - py) * 0.15;
                    vz += (targetZ - pz) * 0.15;
                    // Push along beam direction
                    vx += beam.dir.x * 6;
                    vy += beam.dir.y * 6;
                    vz += beam.dir.z * 6;
                    handled = true;
                }
            }

            if (!handled) {
                // 2) SHIELD particles (orbit around fighter)
                if (myFighter.active && myFighter.shieldStrength > 0.05) {
                    const dx = myFighter.pos.x - px;
                    const dy = myFighter.pos.y - py;
                    const dz = myFighter.pos.z - pz;
                    const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
                    const targetR = BATTLE_SHIELD_RADIUS;
                    const diff = dist - targetR;
                    // Pull/push to shield radius
                    if (dist > 1) {
                        const force = diff * 0.05 * myFighter.shieldStrength;
                        vx += (dx/dist) * force;
                        vy += (dy/dist) * force;
                        vz += (dz/dist) * force;
                    }
                    // Orbital motion (creates rotating shield)
                    const d2D = Math.sqrt(dx*dx + dy*dy + 100);
                    vx += (dy/d2D) * 4 * myFighter.shieldStrength;
                    vy -= (dx/d2D) * 4 * myFighter.shieldStrength;
                    handled = true;
                }
                // 3) CHARGING — pull particles toward fighter into a glowing ball
                else if (myFighter.active && myFighter.charging) {
                    const dx = myFighter.pos.x - px;
                    const dy = myFighter.pos.y - py;
                    const dz = myFighter.pos.z - pz;
                    const distSq = dx*dx + dy*dy + dz*dz + 100;
                    const pull = (2000 + myFighter.chargeAmount * 6000) / distSq;
                    vx += dx * pull * 0.4;
                    vy += dy * pull * 0.4;
                    vz += dz * pull * 0.4;
                    // Compress: prevent collapse to point
                    const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
                    const ballR = 50 + myFighter.chargeAmount * 30;
                    if (dist < ballR && dist > 1) {
                        const out = (ballR - dist) * 0.06;
                        vx -= (dx/dist) * out;
                        vy -= (dy/dist) * out;
                        vz -= (dz/dist) * out;
                    }
                    // Spin
                    const d2D = Math.sqrt(dx*dx + dy*dy + 100);
                    vx += (dy/d2D) * (1 + myFighter.chargeAmount * 4);
                    vy -= (dx/d2D) * (1 + myFighter.chargeAmount * 4);
                    handled = true;
                }
                // 4) IDLE — orbit around fighter loosely
                else if (myFighter.active) {
                    const dx = myFighter.pos.x - px;
                    const dy = myFighter.pos.y - py;
                    const dz = myFighter.pos.z - pz;
                    const distSq = dx*dx + dy*dy + dz*dz + 100;
                    const pull = 1500 / distSq;
                    vx += dx * pull * 0.3;
                    vy += dy * pull * 0.3;
                    vz += dz * pull * 0.3;
                    handled = true;
                }
            }

            // 5) EXPLOSION blast — push outward from explosion centers
            for (let e = 0; e < battle.explosions.length; e++) {
                const exp = battle.explosions[e];
                const dx = px - exp.pos.x;
                const dy = py - exp.pos.y;
                const dz = pz - exp.pos.z;
                const dist = Math.sqrt(dx*dx + dy*dy + dz*dz) || 1;
                if (dist < exp.radius + 100) {
                    const f = exp.life * exp.power * 8 / Math.max(dist, 30);
                    vx += (dx/dist) * f * 5;
                    vy += (dy/dist) * f * 5;
                    vz += (dz/dist) * f * 5;
                }
            }

            if (!handled) {
                // No fighters → drift back gently
                vx -= px * 0.0008;
                vy -= py * 0.0008;
                vz -= pz * 0.0008;
            }
        } else if (isDuelMode) {
            if (supernova.state === 'EXPLODING') {
                // damping handles
            } else if (supernova.state === 'COOLDOWN') {
                vx -= px * 0.002; vy -= py * 0.002; vz -= pz * 0.002;
            } else {
                let target = null;
                if (hasTwoHands) target = particleOwner[i] === 0 ? hands.left : hands.right;
                else if (singleActiveHand) target = singleActiveHand;
                if (target) {
                    const r = applyDuelHandForces(px, py, pz, vx, vy, vz, target);
                    vx = r.vx; vy = r.vy; vz = r.vz;
                } else {
                    vx -= px * 0.0005; vy -= py * 0.0005; vz -= pz * 0.0005;
                }
            }
        } else if (isSwarmMode) {
            if (Date.now() - lastHandTime > 1000) {
                const distSq = px * px + py * py + pz * pz;
                const dist = Math.sqrt(distSq) || 1;
                const orbitSpeed = 8.0 / Math.pow(dist, 0.4);
                vx -= (pz / dist) * orbitSpeed;
                vz += (px / dist) * orbitSpeed;
                if (Math.abs(py) > 50) vy -= py * 0.005;
                vy += Math.sin(px * 0.01 + timeScale) * 0.4;
                vy += Math.cos(pz * 0.01 + timeScale * 0.8) * 0.4;
                if (dist > 900) {
                    vx -= (px / dist) * 0.2; vy -= (py / dist) * 0.2; vz -= (pz / dist) * 0.2;
                } else if (dist < 200) {
                    vx += (px / dist) * 0.8; vz += (pz / dist) * 0.8;
                }
            } else {
                const r = applySingleHandForces(px, py, pz, vx, vy, vz, indexFingerTip);
                vx = r.vx; vy = r.vy; vz = r.vz;
            }
        } else {
            // Shape mode
            const tx = shapeTargets[ix], ty = shapeTargets[iy], tz = shapeTargets[iz];
            const dx = tx - px, dy = ty - py, dz = tz - pz;
            if (musicReactivityEnabled) {
                const sf = SHAPE_FORCE * (1 + bassEnergy * 0.8);
                vx += dx * sf; vy += dy * sf; vz += dz * sf;
                if (beatPulse > 0.3) {
                    const len = Math.sqrt(px * px + py * py + pz * pz) || 1;
                    vx += (px / len) * beatPulse * 4;
                    vy += (py / len) * beatPulse * 4;
                    vz += (pz / len) * beatPulse * 4;
                }
            } else {
                vx += dx * SHAPE_FORCE; vy += dy * SHAPE_FORCE; vz += dz * SHAPE_FORCE;
            }
            const fdx = indexFingerTip.x - px, fdy = indexFingerTip.y - py;
            const fdist = Math.sqrt(fdx * fdx + fdy * fdy);
            if (fdist < 100) { vx -= fdx * 0.1; vy -= fdy * 0.1; }
        }

        // Tiny life jitter
        vx += (Math.random() - 0.5) * 0.05;
        vy += (Math.random() - 0.5) * 0.05;
        vz += (Math.random() - 0.5) * 0.05;

        // Damping
        vx *= DAMPING; vy *= DAMPING; vz *= DAMPING;

        // Speed clamp
        const speed = Math.sqrt(vx * vx + vy * vy + vz * vz);
        if (speed > MAX_VEL) {
            const s = MAX_VEL / speed;
            vx *= s; vy *= s; vz *= s;
        }

        positions[ix] += vx; positions[iy] += vy; positions[iz] += vz;
        pVel[ix] = vx; pVel[iy] = vy; pVel[iz] = vz;
    }

    particles.geometry.attributes.position.needsUpdate = true;
    particles.geometry.attributes.color.needsUpdate = true;

    scene.rotation.y = Math.sin(time * 0.1) * 0.1;

    // Screen shake
    if (shakeAmount > 0.1) {
        camera.position.x = (Math.random() - 0.5) * shakeAmount;
        camera.position.y = (Math.random() - 0.5) * shakeAmount;
        shakeAmount *= 0.88;
    } else {
        camera.position.x *= 0.8;
        camera.position.y *= 0.8;
    }

    renderer.render(scene, camera);
}

window.addEventListener('resize', () => {
    width = window.innerWidth;
    height = window.innerHeight;
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    renderer.setSize(width, height);
});

animate();